namespace rootfinder {

template <class T>
struct RootTraits {
    static_assert(std::numeric_limits<T>::is_specialized && !std::numeric_limits<T>::is_exact,
                  "Type exact ou sans numeric_limits : specialiser rootfinder::RootTraits<T>");
    static T roundoff() { return std::numeric_limits<T>::epsilon(); }
    static T precision() { return std::numeric_limits<T>::epsilon(); }
    static T tiny() { return std::numeric_limits<T>::min(); }
    static constexpr bool newton() { return true; }
};

namespace detail {

// T explicite à l'appel (absT<T>(expr)) : évite les soucis d'expression templates
template <class T>
inline T absT(const T& x) { using std::abs; return abs(x); }

template <class T>
inline void trim(std::vector<T>& p) {  // supprime les coefficients dominants exactement nuls
    while (!p.empty() && p.back() == T(0)) p.pop_back();
}

template <class T>
inline std::vector<T> derivative(const std::vector<T>& p) {
    std::vector<T> d(p.size() - 1);
    for (size_t i = 1; i < p.size(); ++i) d[i - 1] = T(int(i)) * p[i];
    return d;
}

// Horner : p(x), p'(x), et mu = sum |a_i||x|^i (borne de l'erreur d'évaluation)
template <class T>
inline void evalAll(const std::vector<T>& p, const T& x, T& f, T& df, T& mu) {
    const int n = (int)p.size() - 1;
    const T ax = absT<T>(x);
    f = p[n];
    df = T(0);
    mu = absT<T>(p[n]);
    for (int i = n - 1; i >= 0; --i) {
        df = df * x + f;
        f = f * x + p[i];
        mu = mu * ax + absT<T>(p[i]);
    }
}

// Signe de p(x) ; 0 si |p(x)| est indiscernable de zéro (borne d'erreur de Horner)
template <class T, class Tr>
inline int signAt(const std::vector<T>& p, const T& x) {
    T f, df, mu;
    evalAll(p, x, f, df, mu);
    const int n = (int)p.size() - 1;
    const T tol = T(2 * n) * Tr::roundoff() * mu;
    if (absT<T>(f) <= tol) return 0;
    return f > T(0) ? 1 : -1;
}

// Borne de Cauchy : toutes les racines (complexes) vérifient |z| < B
template <class T>
inline T cauchyBound(const std::vector<T>& p) {
    const size_t n = p.size() - 1;
    T m = T(0);
    for (size_t i = 0; i < n; ++i) {
        const T q = absT<T>(p[i] / p[n]);
        if (q > m) m = q;
    }
    return T(1) + m;
}

// Unique racine dans [lo, hi] (p monotone) ; sLo = signe de p(lo), p(hi) de signe opposé.
// Newton sécurisé par dichotomie (type "rtsafe").
template <class T, class Tr>
inline T refine(const std::vector<T>& p, T lo, T hi, int sLo) {
    const T zero = T(0), two = T(2);
    T x = (lo + hi) / two;
    T dxold = hi - lo, dx = dxold;
    T f, df, mu;
    evalAll(p, x, f, df, mu);
    for (int it = 0; it < 1000; ++it) {
        if (f == zero) return x;
        if ((f > zero) == (sLo > 0)) lo = x; else hi = x;  // mise à jour du crochet

        T xn = x;
        bool bisect = !Tr::newton() || (df == zero);
        if (!bisect) {
            xn = x - f / df;
            bisect = (xn < lo || xn > hi || absT<T>(two * f) > absT<T>(dxold * df));
        }
        dxold = dx;
        if (bisect) xn = (lo + hi) / two;
        dx = xn - x;

        const T tol = two * Tr::precision() * absT<T>(xn) + Tr::tiny();
        if (absT<T>(dx) <= tol) return xn;
        x = xn;
        evalAll(p, x, f, df, mu);
    }
    return x;
}

}  // namespace detail

// Racines réelles distinctes, triées par ordre croissant (racine multiple listée une seule fois)
template <class T, class Tr = RootTraits<T>>
std::vector<T> realRoots(std::vector<T> p) {
    using namespace detail;
    const T zero = T(0);
    trim(p);
    const int n = (int)p.size() - 1;
    if (n < 1) return {};
    if (n == 1) return {-p[0] / p[1]};

    const std::vector<T> crit = realRoots<T, Tr>(derivative(p));  // récursion

    T B = cauchyBound(p);
    for (const T& c : crit) {
        const T b = T(1) + absT<T>(c);
        if (b > B) B = b;
    }

    // noeuds : -inf (représenté par -B), points critiques, +inf (représenté par +B)
    const int sPlusInf = p[n] > zero ? 1 : -1;
    const int sMinusInf = (n % 2 == 0) ? sPlusInf : -sPlusInf;

    std::vector<T> x{-B};
    std::vector<int> s{sMinusInf};
    for (const T& c : crit) { x.push_back(c); s.push_back(signAt<T, Tr>(p, c)); }
    x.push_back(B);
    s.push_back(sPlusInf);

    std::vector<T> roots;
    const size_t m = x.size();
    for (size_t j = 1; j + 1 < m; ++j)
        if (s[j] == 0) roots.push_back(x[j]);  // racine multiple sur un point critique
    for (size_t j = 0; j + 1 < m; ++j)
        if (s[j] * s[j + 1] < 0) roots.push_back(refine<T, Tr>(p, x[j], x[j + 1], s[j]));

    std::sort(roots.begin(), roots.end());
    return roots;
}

}  // namespace rootfinder

