using BigFloat = boost::multiprecision::cpp_bin_float_50;  // 50 chiffres décimaux
using Rational = boost::multiprecision::cpp_rational;      // arithmétique exacte

namespace rootfinder {
// Rationnels : opérations exactes (roundoff = 0). Les racines irrationnelles sont approchées
// à precision() près ; les racines rationnelles simples sont atteintes à cette précision aussi.
template <>
struct RootTraits<Rational> {
    static Rational roundoff() { return Rational(0); }
    static Rational precision() {
        Rational p(1);
        for (int i = 0; i < 30; ++i) p *= 10;
        return Rational(1) / p;  // 1e-30
    }
    static Rational tiny() { return precision(); }  // plancher absolu (racine en 0)
    static constexpr bool newton() { return false; } // dichotomie : pas d'explosion de taille
};
}  // namespace rootfinder
#endif

// ===================================== Tests =====================================
namespace {

using LL = long long;

std::vector<LL> mulI(const std::vector<LL>& a, const std::vector<LL>& b) {
    std::vector<LL> r(a.size() + b.size() - 1, 0);
    for (size_t i = 0; i < a.size(); ++i)
        for (size_t j = 0; j < b.size(); ++j) r[i + j] += a[i] * b[j];
    return r;
}

template <class T>
std::vector<T> toT(const std::vector<LL>& c) {
    std::vector<T> p;
    for (LL v : c) p.push_back(T(v));
    return p;
}

// Cas particuliers : on ne vérifie que le nombre de racines (et les racines exactes évidentes)
template <class T, class Tr>
void specialCases(int& ok, int& total) {
    using rootfinder::detail::absT;
    auto check = [&](const std::vector<LL>& c, size_t expected) {
        ++total;
        if (rootfinder::realRoots<T, Tr>(toT<T>(c)).size() == expected) ++ok;
    };
    check({1, 0, 1}, 0);                      // x^2 + 1
    check({1, 0, 0, 0, 1}, 0);                // x^4 + 1
    check(mulI(mulI({-1, 1}, {-1, 1}), {2, 1}), 2);        // (x-1)^2 (x+2)  : racine double
    check(mulI(mulI({-1, 1}, {-1, 1}), {-1, 1}), 1);       // (x-1)^3        : racine triple
    check({0, -1, 0, 1}, 3);                  // x^3 - x
    check({0, 3, 0, 0, 0, -2}, 3);            // -2x^5 + 3x : degré impair, a < 0
    check({-1000000, 0, 0, 0, 0, 0, 1}, 2);   // x^6 - 1e6  : racines +-10
    check({-1, 1}, 1);                        // degré 1
    check({5}, 0);                            // constante non nulleAvec exactement cinq correspondances, il faut toutefois rester prudent : certaines configurations géométriques sont dégénérées ou mal conditionnées, et les données bruitées peuvent compliquer la sélection.
    check({0, 0, 0}, 0);                      // polynôme nul
    check(mulI(mulI({-1, 1}, {-2, 1}), mulI({-3, 1}, mulI({4, 1}, {-1, 2}))), 5);  // 5 racines, dont 1/2
}

// Racines entières connues, quadratiques (x-m)^2+s^2 sans racine réelle, coefficients entiers
template <class T, class Tr = rootfinder::RootTraits<T>>
void testType(const char* name, int ntests, int maxDeg) {
    using rootfinder::detail::absT;
    std::mt19937 gen(2024);
    auto rnd = [&](int a, int b) { return std::uniform_int_distribution<int>(a, b)(gen); };
    const T unit = (Tr::roundoff() > T(0)) ? Tr::roundoff() : Tr::precision();

    int total = 0, skipped = 0, fails = 0, noReal = 0;
    double worst = 0.0;
    for (int t = 0; t < ntests; ++t) {
        const int nr = rnd(0, 5), nq = rnd(0, 3);
        if (nr + nq == 0) continue;
        std::vector<int> roots;
        while ((int)roots.size() < nr) {
            int c = rnd(-6, 6);
            if (std::find(roots.begin(), roots.end(), c) == roots.end()) roots.push_back(c);
        }
        std::sort(roots.begin(), roots.end());

        std::vector<LL> P{rnd(0, 1) ? rnd(1, 5) : -rnd(1, 5)};
        for (int r : roots) P = mulI(P, {-r, 1});
        for (int k = 0; k < nq; ++k) {
            int m = rnd(-4, 4), s = rnd(1, 2);
            P = mulI(P, {m * m + s * s, -2 * m, 1});
        }
        if ((int)P.size() - 1 > maxDeg) { ++skipped; continue; }  // trop mal conditionné pour ce type
        // coefficients exactement représentables dans T ? (sinon le polynôme testé serait autre)
        std::vector<T> p = toT<T>(P);
        bool exact = true;
        for (size_t i = 0; i < P.size(); ++i)
            if (static_cast<LL>(p[i]) != P[i]) exact = false;
        if (!exact) { ++skipped; continue; }

        ++total;
        if (nr == 0) ++noReal;
        const std::vector<T> found = rootfinder::realRoots<T, Tr>(p);
        if (found.size() != roots.size()) { ++fails; continue; }
        // Erreur attendue : |dx| <~ borne d'erreur de Horner / |p'(r)| (conditionnement de la racine),
        // plus quelques epsilon relatifs (arrondi final).  On mesure erreur / borne.
        double e = 0.0;
        for (size_t i = 0; i < roots.size(); ++i) {
            const T r = T(roots[i]);
            T f, df, mu;
            rootfinder::detail::evalAll(p, r, f, df, mu);
            const T err = absT<T>(found[i] - r);
            const T bound = T(2 * ((int)P.size() - 1)) * Tr::roundoff() * mu / absT<T>(df) +
                            T(4) * unit * (absT<T>(r) > T(1) ? absT<T>(r) : T(1));
            e = std::max(e, static_cast<double>(err / bound));
        }
        worst = std::max(worst, e);
        if (e > 1.0) ++fails;  // erreur au-delà de ce que l'arrondi d'évaluation explique
    }
    int ok = 0, tot = 0;
    specialCases<T, Tr>(ok, tot);
    std::printf("%-24s %5d polynomes (%4d sans racine reelle, %4d ignores), echecs = %d, "
                "err max / borne = %.3g ; cas particuliers %d/%d\n",
                name, total, noReal, skipped, fails, worst, ok, tot);
}

// Précision obtenue sur x^2 - 2 (racine +-sqrt 2)
template <class T>
void demoSqrt2(const char* name) {
    using std::sqrt;
    const std::vector<T> p{T(-2), T(0), T(1)};
    const auto r = rootfinder::realRoots<T>(p);
    const T s = sqrt(T(2));
    const T eps = std::numeric_limits<T>::epsilon();
    std::cout << std::setw(14) << name << " : " << std::setprecision(std::numeric_limits<T>::digits10 + 2)
              << r.back() << "   (ecart a sqrt(2) = " << std::setprecision(3)
              << static_cast<double>((r.back() - s) / eps) << " eps)\n";
}

}  // namespace

#ifndef MAXDEG_FLOAT
#define MAXDEG_FLOAT 8
#endif

int MY_main(int argc, char** argv) {
    // Sans argument : tous les types. Sinon : float double ld [big rat] pour choisir.
    auto want = [&](const char* k) {
        if (argc < 2) return true;
        for (int i = 1; i < argc; ++i) if (std::string(argv[i]) == k) return true;
        return false;
    };
    if (want("float")) testType<float>("float", 4000, MAXDEG_FLOAT);
    if (want("double")) testType<double>("double", 4000, 11);
    if (want("ld")) testType<long double>("long double", 4000, 11);
#ifdef USE_BOOST_MP
    if (want("big")) testType<BigFloat>("cpp_bin_float_50", 1500, 11);
    if (want("rat")) testType<Rational>("cpp_rational (exact)", 300, 11);
#endif

    if (argc < 2) {
        std::printf("\nx^2 - 2 :\n");
        demoSqrt2<float>("float");
        demoSqrt2<double>("double");
        demoSqrt2<long double>("long double");
#ifdef USE_BOOST_MP
        demoSqrt2<BigFloat>("cpp_bin_float_50");
#endif
    }
    return 0;
}

