// Racines réelles d'un polynôme réel — approche récursive par les dérivées (théorème de Rolle)
// C++17, aucune dépendance.   g++ -O2 -std=c++17 racines_reelles.cpp -o racines
//
// Principe :
//   * degré 0 : aucune racine ; degré 1 : solution triviale.
//   * degré n : on calcule récursivement les racines réelles de p' (points critiques c_1 < ... < c_k).
//     Sur chacun des intervalles (c_j, c_{j+1}), p est strictement monotone : au plus une racine,
//     présente ssi p(c_j) et p(c_{j+1}) sont de signes opposés -> extraction par bracketing.
//   * intervalles extrêmes (-inf, c_1) et (c_k, +inf) : le signe en l'infini est donné par le
//     coefficient dominant (et la parité du degré) ; si il diffère du signe en c_1 (resp. c_k),
//     on brackete avec une borne de Cauchy qui majore toutes les racines.
//   * si p(c_j) est nul (à l'erreur d'évaluation près), c_j est racine multiple (p(c)=p'(c)=0) :
//     on la renvoie une seule fois.
//
// Convention : p[i] = coefficient de x^i  (ordre croissant des degrés).
/*
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <limits>
#include <random>
#include <utility>
#include <vector>
*/

using Poly = std::vector<double>;
constexpr double EPS = std::numeric_limits<double>::epsilon();

inline void trim(Poly& p) {  // supprime les coefficients dominants exactement nuls
    while (!p.empty() && p.back() == 0.0) p.pop_back();
}

inline Poly derivative(const Poly& p) {
    Poly d(p.size() - 1);
    for (size_t i = 1; i < p.size(); ++i) d[i - 1] = double(i) * p[i];
    return d;
}

// Horner : p(x), p'(x) et mu = sum |a_i| |x|^i (sert à borner l'erreur d'évaluation)
inline void evalAll(const Poly& p, double x, double& f, double& df, double& mu) {
    const int n = (int)p.size() - 1;
    const double ax = std::abs(x);
    f = p[n];
    df = 0.0;
    mu = std::abs(p[n]);
    for (int i = n - 1; i >= 0; --i) {
        df = df * x + f;
        f = f * x + p[i];
        mu = mu * ax + std::abs(p[i]);
    }
}

// Signe de p(x) : 0 si |p(x)| est indiscernable de zéro (borne d'erreur de Horner)
inline int signAt(const Poly& p, double x) {
    double f, df, mu;
    evalAll(p, x, f, df, mu);
    const double tol = 2.0 * double(p.size() - 1) * EPS * mu;
    if (std::abs(f) <= tol) return 0;
    return f > 0 ? 1 : -1;
}

// Borne de Cauchy : toutes les racines (complexes) vérifient |z| < B
inline double cauchyBound(const Poly& p) {
    const size_t n = p.size() - 1;
    double m = 0.0;
    for (size_t i = 0; i < n; ++i) m = std::max(m, std::abs(p[i] / p[n]));
    return 1.0 + m;
}

// Extraction de l'unique racine dans [lo, hi] où p est monotone ; sLo = signe de p(lo) (+-1),
// p(hi) est de signe opposé.  Newton sécurisé par dichotomie (type "rtsafe").
inline double refine(const Poly& p, double lo, double hi, int sLo) {
    double x = 0.5 * (lo + hi);
    double dxold = hi - lo, dx = dxold;
    double f, df, mu;
    evalAll(p, x, f, df, mu);
    for (int it = 0; it < 1000; ++it) {
        if (f == 0.0) return x;
        if ((f > 0) == (sLo > 0)) lo = x; else hi = x;  // mise à jour du crochet

        double xn = 0.0;
        bool bisect = (df == 0.0);
        if (!bisect) {
            xn = x - f / df;
            bisect = (xn < lo || xn > hi || std::abs(2.0 * f) > std::abs(dxold * df));
        }
        dxold = dx;
        if (bisect) xn = 0.5 * (lo + hi);
        dx = xn - x;

        const double tol = 2.0 * EPS * std::abs(xn) + std::numeric_limits<double>::min();
        if (std::abs(dx) <= tol) return xn;
        x = xn;
        evalAll(p, x, f, df, mu);
    }
    return x;
}

// Racines réelles distinctes, triées par ordre croissant (une racine multiple n'est listée qu'une fois)
inline std::vector<double> realRoots(Poly p) {
    trim(p);
    const int n = (int)p.size() - 1;
    if (n < 1) return {};
    if (n == 1) return {-p[0] / p[1]};

    const std::vector<double> crit = realRoots(derivative(p));  // récursion

    double B = cauchyBound(p);
    for (double c : crit) B = std::max(B, 1.0 + std::abs(c));

    // noeuds : -inf (représenté par -B), points critiques, +inf (représenté par +B)
    const int sPlusInf = p[n] > 0 ? 1 : -1;
    const int sMinusInf = (n % 2 == 0) ? sPlusInf : -sPlusInf;

    std::vector<double> x{-B};
    std::vector<int> s{sMinusInf};
    for (double c : crit) { x.push_back(c); s.push_back(signAt(p, c)); }
    x.push_back(B);
    s.push_back(sPlusInf);

    std::vector<double> roots;
    const size_t m = x.size();
    for (size_t j = 1; j + 1 < m; ++j)
        if (s[j] == 0) roots.push_back(x[j]);          // racine multiple située sur un point critique
    for (size_t j = 0; j + 1 < m; ++j)
        if (s[j] * s[j + 1] < 0) roots.push_back(refine(p, x[j], x[j + 1], s[j]));

    std::sort(roots.begin(), roots.end());
    return roots;
}


